async function setInspectionMode(mode){if(!selected||!['single','connections','body'].includes(mode))return;cameraMotion=null;relationTicket++;relationRoles.clear();relationRoot=null;isolated=mode!=='body';if(mode==='connections'){$('#detailContent').dataset.detailView='relations';document.querySelectorAll('[data-detail-tab]').forEach(b=>{const on=b.dataset.detailTab==='relations';b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;});}$('#showConnections').checked=mode==='connections';refresh();renderConnectionInfo();if(mode==='connections'){await updateConnections(selected);if(isolated&&$('#showConnections').checked){const box=new THREE.Box3();for(const o of objects.values())if(o.visible)box.expandByObject(o);if(!box.isEmpty()){const center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3()).length(),direction=camera.position.clone().sub(controls.target).normalize();animateView(center.clone().addScaledVector(direction,Math.max(.3,size*1.6)),center);}}}else if(mode==='single')frameObject(selected);}
