function render(ms=performance.now()){raf=0;if(cameraMotion){const t=Math.min(1,(ms-cameraMotion.start)/420),e=1-Math.pow(1-t,3);camera.position.lerpVectors(cameraMotion.from,cameraMotion.to,e);controls.target.lerpVectors(cameraMotion.fromTarget,cameraMotion.target,e);if(t===1)cameraMotion=null;}controls.update();let moving;if(course?.active&&coursePhase!==null){organMotion.enabled=true;organMotion.time=coursePhase*60/organMotion.bpm;organMotion.last=null;organMotion.tick(ms,true);organMotion.enabled=false;moving=false;}else moving=organMotion.tick(ms,!cutEnabled&&explosion===0&&!document.hidden);renderer.render(scene,camera);positionSelectionLabel();if(moving||cameraMotion)requestRender();}
