async function loadFile(file){if(loaded.has(file))return;if(inflight.has(file))return inflight.get(file);const job=(async()=>{const loader=new GLTFLoader();const draco=new DRACOLoader();draco.setDecoderPath('./vendor/examples/jsm/libs/draco/gltf/');draco.setWorkerLimit(2);loader.setDRACOLoader(draco);try{const gltf=await loader.loadAsync(`./models/${file}.glb`);if(file==='female')gltf.scene.position.set(.006095,.792613,.055516);gltf.scene.updateMatrixWorld(true);gltf.scene.traverse(o=>{if(!o.isMesh)return;const association=gltf.parser.associations.get(o);const node=association?.nodes;const record=catalog.find(r=>r.file===file&&r.node===node);if(!record){o.visible=false;return;}o.userData.record=record;o.material=createTissueMaterial(record,o.geometry);applyPalette(o.material,paletteMode);o.userData.basePosition=o.position.clone();const center=new THREE.Box3().setFromObject(o).getCenter(new THREE.Vector3());o.userData.worldCenter=center.clone();o.material.clippingPlanes=cutPlanes;const dir=separationVector(THREE,record,center);const parentRotation=new THREE.Quaternion();o.parent.getWorldQuaternion(parentRotation);dir.applyQuaternion(parentRotation.invert());const parentScale=o.parent.getWorldScale(new THREE.Vector3());dir.divide(parentScale);o.userData.explodeDirection=dir;objects.set(record.id,o);});scene.add(gltf.scene);loaded.set(file,gltf.scene);organMotion.rebuild(objects,sex);refresh();}finally{draco.dispose();}})();inflight.set(file,job);try{await job;}finally{inflight.delete(file);}}
