function frameObject(o){if(!o)return;const box=new THREE.Box3().setFromObject(o),center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3());const rect=mount.getBoundingClientRect(),aspect=rect.width/Math.max(1,rect.height)||camera.aspect||1;const fov=(camera.fov||39)*Math.PI/180,limit=Math.min(fov/2,Math.atan(Math.tan(fov/2)*aspect)),distance=Math.max(.12,size.length()*.55/Math.sin(limit));const direction=camera.position.clone().sub(controls.target).normalize();animateView(center.clone().addScaledVector(direction,distance),center);}
