function matches(query,reference=sex){const words=normalize(query).trim().split(/\s+/).filter(Boolean);if(!words.length)return[];return catalog.filter(r=>recordSex(r)===reference).filter(r=>words.every(w=>r.search.includes(w))).sort((a,b)=>{const an=normalize(displayName(a.name)),bn=normalize(displayName(b.name)),q=normalize(query);return Number(bn.startsWith(q))-Number(an.startsWith(q))||an.length-bn.length;});}
let searchPage=0,lastSearchQuery='';
function search(){
 const q=$('#search').value.trim(),list=$('#searchResults');list.hidden=!q;if(!q){searchPage=0;lastSearchQuery='';return;}if(q!==lastSearchQuery){searchPage=0;lastSearchQuery=q;}
 const found=matches(q),pages=Math.max(1,Math.ceil(found.length/60));searchPage=Math.min(searchPage,pages-1);
 if(found.length){list.innerHTML='<p id="searchPageStatus" role="status">'+found.length+' eşleşme'+(pages>1?' · Sayfa '+(searchPage+1)+' / '+pages:'')+'</p>'+found.slice(searchPage*60,(searchPage+1)*60).map(r=>'<button data-id="'+esc(r.id)+'">'+esc(displayName(r.name))+'<small>'+esc(terminologyFor(r)?.latin||cleanName(r.name))+' · '+esc(layerName(r.layer))+(explanationFor(r).scope==='specific'?' · Yapıya özel açıklama':explanationFor(r).scope==='parent'?' · Ana yapı açıklaması':' · Genel doku bilgisi')+'</small></button>').join('')+(pages>1?'<div class="search-pagination"><button data-search-page="-1" '+(!searchPage?'disabled':'')+'>← Önceki</button><button data-search-page="1" '+(searchPage===pages-1?'disabled':'')+'>Sonraki →</button></div>':'');
 }else{const other=sex==='male'?'female':'male',count=matches(q,other).length;list.innerHTML='<p>Yapı bulunamadı. Türkçe, Latince veya İngilizce anatomik adı deneyin.</p>'+(count?'<button data-search-sex="'+other+'">'+(other==='female'?'Kadın':'Erkek')+' referansında '+count+' eşleşme var · Referansı aç →</button>':'');}
}
async function selectById(id){const r=catalog.find(r=>r.id===id);if(!r||recordSex(r)!==sex)throw Error('Yapı bu referansta bulunamadı');region='all';$('#region').value='all';$('#cutAxis').value='none';applyCut();const reference=sex;await loadLayer(r.layer);if(sex!==reference||recordSex(r)!==sex)throw Error('Referans değişti; yapıyı yeniden seç.');const o=objects.get(id);if(!o)throw Error('3B parça bulunamadı');$('#showConnections').checked=false;choose(o,{focus:true,isolate:true});return{id:r.id,name:displayName(r.name),layer:r.layer};}
