let quizQueue=[],quizIndex=0,quizScore=0,quizAnswered=false,quizWrong=[];
function savedMistakes(){try{const ids=JSON.parse(localStorage.getItem('anatomi-mistakes')||'[]');return Array.isArray(ids)?ids.filter(x=>typeof x==='string'):[];}catch{return[];}}
function saveMistakes(ids){try{localStorage.setItem('anatomi-mistakes',JSON.stringify([...new Set(ids)]));}catch{}}
function startQuiz(repeat=false){const wrong=savedMistakes();quizQueue=questionSet(sex,repeat?wrong:[]);if(repeat&&!wrong.length){toast('Tekrar edilecek yanlış cevabın yok.');return;}if(!quizQueue.length){toast('Bu referans için tekrar edilecek soru yok.');return;}quizIndex=0;quizScore=0;quizWrong=[];if(!$('#quizDialog').open)$('#quizDialog').showModal();renderQuiz();}
function renderQuiz(){quizAnswered=false;const q=quizQueue[quizIndex];if(!q){$('#quizContent').innerHTML='<div class="quiz-result"><b>'+quizScore+' / '+quizQueue.length+' doğru</b><p>'+quizWrong.length+' soruyu tekrar çalışabilirsin. Yanlışlar yalnızca bu cihazda saklanır.</p></div><div class="quiz-buttons"><button id="quizRestart">Yeni tur</button><button id="quizRepeat">Yanlışları tekrar et</button></div>';$('#quizRestart').onclick=()=>startQuiz();$('#quizRepeat').onclick=()=>startQuiz(true);return;}$('#quizContent').innerHTML='<p class="quiz-progress">Soru '+(quizIndex+1)+' / '+quizQueue.length+' · '+(sex==='female'?'Kadın':'Erkek')+' referansı</p><h3>'+esc(q.q)+'</h3>'+q.options.map((s,i)=>'<button class="quiz-option" data-answer="'+i+'">'+esc(s)+'</button>').join('')+'<div id="quizFeedback" aria-live="polite"></div>';document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(quizAnswered)return;quizAnswered=true;const index=Number(b.dataset.answer),result=answerQuestion(q,index);let mistakes=savedMistakes();if(result.correct){quizScore++;mistakes=mistakes.filter(id=>id!==q.id);}else{quizWrong.push(q.id);mistakes.push(q.id);}saveMistakes(mistakes);document.querySelectorAll('[data-answer]').forEach(x=>{x.disabled=true;if(Number(x.dataset.answer)===q.correct)x.classList.add('correct');});if(!result.correct)b.classList.add('wrong');$('#quizFeedback').innerHTML='<div class="quiz-result">'+(result.correct?'Doğru. ':'Doğru yanıt: '+esc(q.options[q.correct])+'. ')+esc(result.explanation)+'</div><div class="quiz-buttons"><button id="quizModel">Modelde incele ↗</button><button id="quizNext">'+(quizIndex+1===quizQueue.length?'Sonuçlar':'Sonraki soru')+'</button></div>';$('#quizNext').onclick=()=>{quizIndex++;renderQuiz();};$('#quizModel').onclick=async()=>{const r=matches(q.target).find(r=>isExactTopic(r.name,topicFor(r.name)))||matches(q.target)[0];if(!r){toast('Bu yapı seçili referansta ayrı modellenmemiş.');return;}$('#quizDialog').close();labels=true;$('#showLabels').checked=true;try{await selectById(r.id);}catch{toast('Model yüklenemedi.');}};});}
